TWComponent.script:
try{
	if (tw.local.isSuccessful) {
 
		var accountListLen=0;
		
		for (var i=0 ; i< tw.local.accountsList2.listLength; i++){					
			accountListLen = tw.local.accountsList.listLength ;
			tw.local.accountsList.insertIntoList(accountListLen, tw.local.accountsList2[i]);						
		}	
	}
		 		
} catch (err) {
	tw.local.errorMsg = err.message;
	throw new Error(tw.local.errorMSG);
	
}

